from pathlib import Path
p=Path('/mnt/data/aifilmwork/assets/js/app.js');s=p.read_text()
# map aliases to chosen saved characters automatically and validate targets
s=s.replace('''  const p={id:crypto.randomUUID(),title:$("#projectTitle").value.trim(),prompt:$("#projectPrompt").value.trim(),direction:$("#projectDirection").value.trim(),characterIds:[...$("#projectCharacters").selectedOptions].map(o=>o.value),aliases,language:$("#projectLanguage").value,ratio:$("#projectRatio").value,duration:Number($("#projectDuration").value),scenes:[],created_at:new Date().toISOString()};''','''  const chosenIds=[...$("#projectCharacters").selectedOptions].map(o=>o.value);
  for(const [alias,target] of Object.entries(aliases)){const match=state.characters.find(c=>c.name.toLowerCase()===target.toLowerCase());if(!match){toast(`Mapping target "${target}" is not in your saved character library.`);return;}if(!chosenIds.includes(match.id))chosenIds.push(match.id);}
  const p={id:crypto.randomUUID(),title:$("#projectTitle").value.trim(),prompt:$("#projectPrompt").value.trim(),direction:$("#projectDirection").value.trim(),characterIds:chosenIds,aliases,language:$("#projectLanguage").value,ratio:$("#projectRatio").value,duration:Number($("#projectDuration").value),scenes:[],created_at:new Date().toISOString()};''')
# load dialogue line data + signed audio URL from cloud JSON
old='''dialogue_lines:(()=>{try{const d=JSON.parse(s.dialogue_text);return d.__dialogueLines||parseDialogueLines(s.dialogue_text);}catch{return parseDialogueLines(s.dialogue_text);}})(),voice_language:s.voice_language'''
new='''dialogue_lines:await Promise.all((()=>{try{const d=JSON.parse(s.dialogue_text);return d.__dialogueLines||parseDialogueLines(s.dialogue_text);}catch{return parseDialogueLines(s.dialogue_text);}})().map(async line=>({...line,audio:line.audio_path?await StudioDB.signedUrl("project-assets",line.audio_path):""}))),voice_language:s.voice_language'''
s=s.replace(old,new)
# add audio path upload for every dialogue line before row creation, encode metadata only
old='''let voicePath=s.voice_audio_path||null;if(s.dialogue_lines?.some(x=>x.audio?.startsWith("data:"))){const audioLine=s.dialogue_lines.find(x=>x.audio?.startsWith("data:"));const audioFile=await dataUrlToFile(audioLine.audio,`scene-${i+1}-voice.mp3`);voicePath=await StudioDB.uploadPrivate("project-assets",`projects/${state.activeProject.id}/scene-${i+1}-voice-${crypto.randomUUID()}.mp3`,audioFile);s.voice_audio_path=voicePath;}const row={project_id:state.activeProject.id,character_id:s.character_id||null,character_ids:s.character_ids||[],scene_order:i+1,duration_seconds:s.duration,visual_prompt:s.visual_prompt,dialogue_text:JSON.stringify({__dialogueLines:s.dialogue_lines||[]}),voice_language:s.voice_language,sound_prompt:s.sound_prompt,reference_image_path:refPath,voice_audio_path:voicePath};'''
new='''for(let j=0;j<(s.dialogue_lines||[]).length;j++){const line=s.dialogue_lines[j];if(line.audio?.startsWith("data:")){const audioFile=await dataUrlToFile(line.audio,`scene-${i+1}-line-${j+1}.mp3`);line.audio_path=await StudioDB.uploadPrivate("project-assets",`projects/${state.activeProject.id}/scene-${i+1}-line-${j+1}-${crypto.randomUUID()}.mp3`,audioFile);}}const dialogueData=(s.dialogue_lines||[]).map(({audio,...line})=>line);const row={project_id:state.activeProject.id,character_id:s.character_id||null,character_ids:s.character_ids||[],scene_order:i+1,duration_seconds:s.duration,visual_prompt:s.visual_prompt,dialogue_text:JSON.stringify({__dialogueLines:dialogueData}),voice_language:s.voice_language,sound_prompt:s.sound_prompt,reference_image_path:refPath,voice_audio_path:null};'''
if old not in s: print('old cloud voice persistence not found')
else: s=s.replace(old,new)
# preserve audio in readDialogueLines
s=s.replace('''function readDialogueLines(card){return $$("[data-dialogue-line]",card).map(row=>({speaker:row.querySelector("[data-line-speaker]")?.value||"Narrator",text:row.querySelector("[data-line-text]")?.value.trim()||"",language:row.querySelector("[data-line-language]")?.value||"en",voice_style:row.querySelector("[data-line-style]")?.value||"Warm, smooth"})).filter(x=>x.text);}''','''function readDialogueLines(card){const scene=state.activeProject?.scenes?.[Number(card.dataset.scene)];return $$("[data-dialogue-line]",card).map((row,j)=>({speaker:row.querySelector("[data-line-speaker]")?.value||"Narrator",text:row.querySelector("[data-line-text]")?.value.trim()||"",language:row.querySelector("[data-line-language]")?.value||"en",voice_style:row.querySelector("[data-line-style]")?.value||"Warm, smooth",audio:scene?.dialogue_lines?.[j]?.audio||"",audio_path:scene?.dialogue_lines?.[j]?.audio_path||null})).filter(x=>x.text);}''')
# scene image prompt uses current dialogue editor lines, not hidden legacy textarea
s=s.replace('''const card=imageButton.closest(".scene-card"),visual=card.querySelector('[data-field="visual_prompt"]').value,dialogue=card.querySelector('[data-field="dialogue"]').value;''','''const card=imageButton.closest(".scene-card"),visual=card.querySelector('[data-field="visual_prompt"]').value,dialogue=readDialogueLines(card).map(x=>`${x.speaker}: ${x.text}`).join("\\n");''')
# don't append no saved char instruction incorrectly if user intentionally empty; already no selected returns prompt
# TTS health and browser notice
s=s.replace('''Connect your free Cloudflare AI Worker in Studio Settings first.''','''Connect your Cloudflare AI Worker. English AI voice generation is supported; Sinhala can use browser preview.''')
p.write_text(s)

# CSS additions
css=Path('/mnt/data/aifilmwork/assets/css/style.css');c=css.read_text();c += '''\n.character-setup-block{border:1px solid var(--line);background:#fafbff;border-radius:11px;padding:14px;display:grid;gap:10px}.character-setup-block h3{margin:0;font-size:13px}.character-setup-block .helper{margin:0}.dialogue-line{border:1px solid #e7e9f2;border-radius:10px;padding:12px;margin:10px 0;background:#fcfcff}.dialogue-line-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px;font-size:12px}.dialogue-line .scene-fields{gap:9px}.dialogue-line .ai-action-row{margin-top:0}.upload-scene-label{display:inline-flex;align-items:center;cursor:pointer}.generated-voice-audio{display:block;width:100%;max-width:420px;margin-top:9px}.scene-card h4{font-size:13px;margin:15px 0 6px;color:var(--ink)}\n''';css.write_text(c)

# Update readme and worker setup docs with TTS note and migration
r=Path('/mnt/data/aifilmwork/README.md');t=r.read_text();t += '''\n\n## Character, dialogue and voice controls (2026-11-10)\n- Select saved characters in Project Setup and map story aliases such as `Jessica -> MAYA`.\n- Scene cards detect saved names/aliases and allow multiple character assignment.\n- Scene artwork can be regenerated, removed, or replaced with an uploaded image. The current FLUX text-to-image route is text-only and cannot guarantee exact reference-image identity.\n- Dialogue is edited per speaker. English AI voice can be generated through Cloudflare Workers AI MeloTTS; voice audio can be deleted and regenerated. Sinhala is currently browser voice preview only.\n- Apply `supabase/migrations/20261110_scene_voice_audio.sql` to existing Supabase projects before syncing generated voice audio.\n''';r.write_text(t)
